1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	public class BuildOwner {
10	
11	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
12	        Owner owner = ownerMapper.toOwner(request);
13	        // The effective registration date (supplied in the request, or the server date when omitted)
14	        // must fall on a business day: a weekend date rolls forward to the next Monday. Every value
15	        // derived from it (membership number year, daily-limit bucket) then uses this adjusted date.
16	        owner.setRegistrationDate(RegistrationDates.effective(owner.getRegistrationDate()));
17	        built.set(owner);
18	    }
19	}
