144	    public String getPostcode() {
145	        return this.postcode;
146	    }
147	
148	    public void setPostcode(String postcode) {
149	        this.postcode = postcode;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    /**
161	     * The stored {@link #getTelephone() telephone} formatted for humans by {@link TelephoneFormatter}:
162	     * the country code, a space, then the national digits grouped in threes (e.g. {@code +61412345678}
163	     * -> {@code +61 412 345 678}). The raw {@link #getTelephone() telephone} stays in E.164 form.
164	     */
165	    public String getTelephoneDisplay() {
166	        return TelephoneFormatter.toDisplay(this.telephone);
167	    }
168	
169	    public String getEmail() {
170	        return this.email;
171	    }
172	
173	    public void setEmail(String email) {
174	        this.email = email;
175	    }
176	
177	    public String getTitle() {
178	        return this.title;
179	    }
180	
181	    public void setTitle(String title) {
182	        this.title = title;
183	    }
184	
185	    /**
186	     * The owner's salutation: the {@link #getTitle() title} followed by a single space and the
187	     * {@link #getLastName() last name} (e.g. {@code "DR Franklin"}), or just the last name when no
188	     * title was supplied. Derived per response, not persisted.
189	     */
190	    public String getSalutation() {
191	        if (this.title == null || this.title.isBlank()) {
192	            return this.getLastName();
193	        }
194	        return this.title + " " + this.getLastName();
195	    }
196	
197	    public LocalDate getRegistrationDate() {
198	        return this.registrationDate;
199	    }
200	
201	    public void setRegistrationDate(LocalDate registrationDate) {
202	        this.registrationDate = registrationDate;
203	    }
204	
205	    /**
206	     * The fiscal year a {@code date} belongs to, as a four-digit year. The fiscal year starts on 1 July
207	     * and is identified by the calendar year in which it ends: a date on or after 1 July of year
208	     * {@code Y} belongs to the fiscal year ending in {@code Y + 1}, while a date in January to June of
209	     * year {@code Y} belongs to the fiscal year ending in {@code Y}.
210	     */
211	    public static int fiscalYear(LocalDate date) {
212	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
213	    }
214	
215	    /**
216	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the last two digits of the
217	     * {@link #fiscalYear(LocalDate) fiscal year} of the business-day-adjusted
218	     * {@link #getRegistrationDate() registrationDate} (e.g. a registration on 2026-10-02 falls in the
219	     * fiscal year ending June 2027, so {@code "FY27"}). {@code null} when no registration date is
220	     * present. Derived per response.
221	     */
222	    public String getFiscalYear() {
223	        if (this.registrationDate == null) {
224	            return null;
225	        }
226	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
227	    }
228	
229	    public LocalDate getBirthDate() {
230	        return this.birthDate;
231	    }
232	
233	    public void setBirthDate(LocalDate birthDate) {
234	        this.birthDate = birthDate;
235	    }
236	
237	    /**
238	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
239	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
240	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
241	     * (so the field is absent from the response) or the registration date is unknown.
242	     */
243	    public String getAgeBand() {
244	        if (this.birthDate == null || this.registrationDate == null) {
245	            return null;
246	        }
247	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
248	        if (age < 18) {
249	            return "MINOR";
250	        }
251	        if (age < 65) {
252	            return "ADULT";
253	        }
254	        return "SENIOR";
255	    }
256	
257	    public String getCustomerCode() {
258	        return this.customerCode;
259	    }
260	
261	    public void setCustomerCode(String customerCode) {
262	        this.customerCode = customerCode;
263	    }
264	
265	    public String getMembershipNumber() {
266	        return this.membershipNumber;
267	    }
268	
269	    public void setMembershipNumber(String membershipNumber) {
270	        this.membershipNumber = membershipNumber;
271	    }
272	
273	    public String getHouseholdId() {
274	        return this.householdId;
275	    }
276	
277	    public void setHouseholdId(String householdId) {
278	        this.householdId = householdId;
279	    }
280	
281	    public Integer getNamesakeCount() {
282	        return this.namesakeCount;
283	    }
284	
285	    public void setNamesakeCount(Integer namesakeCount) {
286	        this.namesakeCount = namesakeCount;
287	    }
288	
289	    /**
290	     * Whether this owner has been soft-deleted. A {@code DELETE /api/owners/{id}} sets this true and
291	     * retains the record rather than removing it; a newly created owner is false. Soft-deleted owners
292	     * are still returned by {@code GET /api/owners/{id}} but are ignored by the create endpoint's
293	     * duplicate/identity checks (see {@code CheckHouseholdUnique}).
294	     */
295	    public boolean isDeleted() {
296	        return this.deleted;
297	    }
298	
299	    public void setDeleted(boolean deleted) {
300	        this.deleted = deleted;
301	    }
302	
303	    /**
304	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
305	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
306	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
307	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
308	     * count is recomputed on each read because household membership changes as owners come and go.
309	     */
310	    public void setHouseholdSize(Integer householdSize) {
311	        this.householdSize = householdSize;
312	    }
313	
314	    /**
315	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
316	     * have already been created for this owner's registration day. Computed per request, not persisted.
317	     */
318	    public Boolean getBulkSignupWarning() {
319	        return this.bulkSignupWarning;
320	    }
321	
322	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
323	        this.bulkSignupWarning = bulkSignupWarning;
324	    }
325	
326	    /**
327	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
328	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
329	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
330	     * {@code sharesHousehold}), which is not a suspected duplicate.
331	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
332	     */
333	    public Boolean getPossibleDuplicate() {
334	        return this.possibleDuplicate;
335	    }
336	
337	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
338	        this.possibleDuplicate = possibleDuplicate;
339	    }
340	
341	    /**
342	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
343	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
344	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
345	     */
346	    public Integer getPossibleDuplicateOf() {
347	        return this.possibleDuplicateOf;
348	    }
349	
350	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
351	        this.possibleDuplicateOf = possibleDuplicateOf;
352	    }
353	
354	    /**
355	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
356	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
357	     * {@link #setHouseholdSize(Integer)}); add 3 for a tenure of at least one elapsed fiscal year, i.e.
358	     * the {@code registrationDate} falls in an earlier {@link #fiscalYear(LocalDate) fiscal year} than
359	     * today (fiscal years start 1 July). A newly created owner has zero tenure, so a fresh owner scores
360	     * at most 5 points (2 + 1 + 2).
361	     */
362	    public int getMembershipPoints() {
363	        int points = 0;
364	        boolean hasEmail = this.email != null && !this.email.isBlank();
365	        if (hasEmail) {
366	            points += 2;
367	        }
368	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
369	        if (unique) {
370	            points += 1;
371	        }
372	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
373	        if (largeHousehold) {
374	            points += 2;
375	        }
376	        boolean tenured = this.registrationDate != null
377	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1;
378	        if (tenured) {
379	            points += 3;
380	        }
381	        return points;
382	    }
383	
384	    /**
385	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
386	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
387	     */
388	    public int getMembershipLevel() {
389	        int points = getMembershipPoints();
390	        if (points <= 1) {
391	            return 1;
392	        }
393	        if (points <= 3) {
394	            return 2;
395	        }
396	        if (points <= 5) {
397	            return 3;
398	        }
399	        return 4;
400	    }
401	
402	    /**
403	     * Fixed city-to-region table mapping each known city to its canonical region string.
404	     */
405	    private static final Map<String, String> CITY_REGION = Map.of(
406	        "Sydney", "NSW",
407	        "Melbourne", "VIC",
408	        "Brisbane", "QLD");
409	
410	    /**
411	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
412	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
413	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
414	     */
415	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
416	        "NSW", new int[] {2000, 2099},
417	        "VIC", new int[] {3000, 3099},
418	        "QLD", new int[] {4000, 4099});
419	
420	    /**
421	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
422	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
423	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
424	     */
425	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
426	        "NSW", "Australia/Sydney",
427	        "VIC", "Australia/Melbourne",
428	        "QLD", "Australia/Brisbane");
429	
430	    /**
431	     * The canonical region for {@code city} derived from the fixed city-to-region table
432	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
433	     * city is not in the table. The single source of truth for the create-time postcode range check in
434	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
435	     */
436	    public static String regionOf(String city) {
437	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
438	    }
439	
440	    /**
441	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
442	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
443	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
444	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
445	     * postcode range check.
446	     */
447	    public static int[] postcodeRangeOf(String region) {
448	        return REGION_POSTCODES.get(region);
449	    }
450	
451	    /**
452	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
453	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
454	     * range.
455	     */
456	    public static String regionOfPostcode(String postcode) {
457	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
458	            return null;
459	        }
460	        int value = Integer.parseInt(postcode);
461	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
462	            int[] range = entry.getValue();
463	            if (value >= range[0] && value <= range[1]) {
464	                return entry.getKey();
465	            }
466	        }
467	        return null;
468	    }
469	
470	    /**
471	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
472	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
473	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
474	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
475	     * customer code is assigned.
476	     */
477	    public String getLocality() {
478	        if (this.customerCode == null) {
479	            return "UNKNOWN";
480	        }
481	        int dash = this.customerCode.indexOf('-');
482	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
483	    }
484	
485	    /**
486	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
487	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
488	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
489	     * locality maps to no known region.
490	     */
491	    public String getTimezone() {
492	        return REGION_TIMEZONE.get(getLocality());
493	    }
494	
495	    /**
496	     * The single Luhn check digit (0-9) computed over the digits contained in the
497	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
498	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
499	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
500	     */
501	    public int getCheckDigit() {
502	        String code = this.customerCode;
503	        if (code == null) {
504	            return 0;
505	        }
506	        int sum = 0;
507	        boolean dbl = true;
508	        for (int i = code.length() - 1; i >= 0; i--) {
509	            char c = code.charAt(i);
510	            if (c < '0' || c > '9') {
511	                continue;
512	            }
513	            int d = c - '0';
514	            if (dbl) {
515	                d *= 2;
516	                if (d > 9) {
517	                    d -= 9;
518	                }
519	            }
520	            sum += d;
521	            dbl = !dbl;
522	        }
523	        return (10 - (sum % 10)) % 10;
524	    }
525	
526	    /**
527	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
528	     * {@code "PHONE"}.
529	     */
530	    public String getContactPreference() {
531	        boolean hasEmail = this.email != null && !this.email.isBlank();
532	        return hasEmail ? "EMAIL" : "PHONE";
533	    }
534	
535	    /**
536	     * The single canonical format of an owner's derived identity key:
537	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
538	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
539	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
540	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
541	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
542	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
543	     * {@code CheckHouseholdUnique}).
544	     */
545	    public static String identityKey(String telephone, String email, String householdId) {
546	        String tel = (telephone == null) ? "" : telephone;
547	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
548	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
549	        return tel + "|" + mail + "|" + household;
550	    }
551	
552	    /**
553	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
554	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
555	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
556	     */
557	    public String getIdentityKey() {
558	        return identityKey(this.telephone, this.email, this.householdId);
559	    }
560	
561	    protected Set<Pet> getPetsInternal() {
562	        if (this.pets == null) {
563	            this.pets = new HashSet<>();
564	        }
565	        return this.pets;
566	    }
567	
568	    protected void setPetsInternal(Set<Pet> pets) {
569	        this.pets = pets;
570	    }
571	
572	    public List<Pet> getPets() {
573	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
574	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
575	        return Collections.unmodifiableList(sortedPets);
576	    }
577	
578	    public void setPets(List<Pet> pets) {
579	        this.pets = new HashSet<>(pets);
580	    }
581	
582	    public void addPet(Pet pet) {
583	        getPetsInternal().add(pet);
584	        pet.setOwner(this);
585	    }
586	
587	    /**
588	     * Return the Pet with the given name, or null if none found for this Owner.
589	     *
590	     * @param name to test
591	     * @return true if pet name is already in use
592	     */
593	    public Pet getPet(String name) {
594	        return getPet(name, false);
595	    }
596	
597	    /**
598	     * Return the Pet with the given name, or null if none found for this Owner.
599	     *
600	     * @param name to test
601	     * @return true if pet name is already in use
602	     */
603	    public Pet getPet(String name, boolean ignoreNew) {
604	        name = name.toLowerCase();
605	        for (Pet pet : getPetsInternal()) {
606	            if (!ignoreNew || !pet.isNew()) {
607	                String compName = pet.getName();
608	                compName = compName.toLowerCase();
609	                if (compName.equals(name)) {
610	                    return pet;
611	                }
612	            }
613	        }
614	        return null;
615	    }
616	
617	    public Pet getPet(Integer petId) {
618	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
619	    }
620	
621	    @Override
622	    public String toString() {
623	        return new ToStringCreator(this)
624	
625	            .append("id", this.getId())
626	            .append("new", this.isNew())
627	            .append("lastName", this.getLastName())
628	            .append("firstName", this.getFirstName())
629	            .append("address", this.address)
630	            .append("city", this.city)
631	            .append("telephone", this.telephone)
632	            .toString();
633	    }
634	}
